package fraymus.workspace;
import java.awt.image.BufferedImage;
import java.util.*;
import org.json.JSONObject;

/** Explicit per-run research choice; the incumbent remains the default. */
final class ObservationMethods129 {
 static final String DEFAULT="legacy-flow",CANDIDATE="scale-aware-129";
 static String policy(JSONObject input){String p=input.optString("trackerPolicy",DEFAULT);if(!Set.of(DEFAULT,CANDIDATE,"ambiguity-guard-144","ambiguity-monitor-144","reference-confirmation-143","reference-monitor-143","reference-seed-143","partial-reference-142","partial-monitor-142","partial-seed-142","recovery-guard-141","recovery-monitor-141","corroborated-guard-140","monitor-only-140","foreground-guard-139","monitor-only-139","drift-guard-138","monitor-only-138","verified-memory-137","seed-only-137","seed-anchored-136","appearance-continuity-135","continuity-no-bank-135","identity-recovery-134","object-flow-130","renewing-flow-131","association-contact-133").contains(p))throw new IllegalArgumentException("Choose an installed tracking method");return p;}
 static ImageTracker create(JSONObject run,String id,String label,BufferedImage first,PixelTracker.Box box){String p=policy(run);return AmbiguityAudit144.uses(p)?new AmbiguityGuard144(id,label,first,box,run.getJSONObject("referenceMemory137"),p.equals("ambiguity-guard-144")):ConfirmationAudit143.uses(p)?new AppearanceConfirmation143(id,label,first,box,run.getJSONObject("referenceMemory137"),!p.equals("reference-monitor-143"),!p.equals("reference-seed-143")):PartialAudit142.uses(p)?new PartialRecovery142(id,label,first,box,run.getJSONObject("referenceMemory137"),!p.equals("partial-monitor-142"),!p.equals("partial-seed-142")):ReferenceMemory137.uses(p)?new VerifiedMemoryFlow137(id,label,first,box,run.getJSONObject("referenceMemory137"),p.equals("verified-memory-137")):create(p,id,label,first,box);}
 static ImageTracker create(String policy,String id,String label,BufferedImage first,PixelTracker.Box box){return switch(policy){case "recovery-guard-141"->new LossRecovery141(id,label,first,box,true);case "recovery-monitor-141"->new LossRecovery141(id,label,first,box,false);case "corroborated-guard-140"->new CorroboratedGuard140(id,label,first,box,true);case "monitor-only-140"->new CorroboratedGuard140(id,label,first,box,false);case "foreground-guard-139"->new ForegroundGuard139(id,label,first,box,true);case "monitor-only-139"->new ForegroundGuard139(id,label,first,box,false);case "drift-guard-138"->new DriftGuard138(id,label,first,box,true);case "monitor-only-138"->new DriftGuard138(id,label,first,box,false);case "seed-anchored-136"->new AppearanceFlow136(id,label,first,box,true);case "appearance-continuity-135"->new AppearanceFlow135(id,label,first,box,true);case "continuity-no-bank-135"->new AppearanceFlow135(id,label,first,box,false);case "identity-recovery-134"->new IdentityRecovery134(id,label,first,box);case "association-contact-133"->new AssociationContact133(id,label,first,box);case DEFAULT->new FlowTracker(id,label,first,box);case "object-flow-130"->new ObjectFlow130(id,label,first,box);case "renewing-flow-131"->new RenewingFlow131(id,label,first,box);case CANDIDATE->new ScaleAwareFlow129(id,label,first,box);default->throw new IllegalArgumentException("Unknown tracking method");};}
 static String identity(String version){var classes=new TreeMap<String,Class<?>>();for(Class<?> c:List.of(ObservationMethods129.class,AmbiguityGuard144.class,AmbiguityAudit144.class,ReferenceSearch143.class,AppearanceConfirmation143.class,ConfirmationAudit143.class,PartialSearch142.class,PartialRecovery142.class,PartialAudit142.class,LossRecovery141.class,RecoverySearch141.class,LossRecoveryAudit141.class,CorroboratedGuard140.class,CorroboratedAudit140.class,RestorationGate140.class,SpatialEvidence139.class,ForegroundGuard139.class,ForegroundAudit139.class,AppearanceEvidence138.class,DriftGuard138.class,DriftAudit138.class,ParsedJson137.class,ReferenceMemory137.class,ReferenceAudit137.class,VerifiedMemoryFlow137.class,AppearanceFlow136.class,AppearanceFlow135.class,IdentityRecovery134.class,AssociationContact133.class,VisualSupport133.class,ObservationFilter.class,WorldObservationStore.class,FlowTracker.class,ObjectFlow130.class,RenewingFlow131.class,ScaleAwareFlow129.class,AdaptiveTracker.class,PixelTracker.class))collect(c,classes);var s=new StringBuilder(version);for(var entry:classes.entrySet())try(var in=entry.getValue().getResourceAsStream(entry.getKey().substring(entry.getKey().lastIndexOf('.')+1)+".class")){if(in==null)throw new IllegalStateException("Missing tracking implementation class");s.append(entry.getKey()).append(PerceptionStore.hash(in.readAllBytes()));}catch(Exception e){throw new IllegalStateException(e);}return MeasurementStore.hash(s.toString());}
 private static void collect(Class<?> c,Map<String,Class<?>> found){if(found.putIfAbsent(c.getName(),c)==null)for(Class<?> nested:c.getDeclaredClasses())collect(nested,found);}
}
